function topDownOrder(tree, root) {
  const order = [];
  const seen = new Set([root]);
  const queue = [root];
  while (queue.length) {
    const x = queue.shift();
    order.push(x);
    for (const c of tree[x] || []) if (!seen.has(c)) { seen.add(c); queue.push(c); }
  }
  return order;
}

function stubsFor(tree, baseline) {
  const inB = new Set(baseline);
  const out = new Set();
  for (const m of baseline) for (const c of tree[m] || []) if (!inB.has(c)) out.add(c);
  return [...out].sort();
}

function driversFor(tree, baseline) {
  const inB = new Set(baseline);
  const out = new Set();
  for (const k of Object.keys(tree)) if (!inB.has(k) && (tree[k] || []).some((c) => inB.has(c))) out.add(k);
  return [...out].sort();
}
